// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "../bridge";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface MedicationWorklistItemOut {
  kind: "VerbalOrderToCountersign" | "QueryOpen" | "NoWristband" | "OwnMedicineToIdentify" | "OwnMedicineToHandBack" | "RecallOpen" | "ExpiredWardStock";
  title: string;
  detail: string | null;
  due_at: string | null;
  is_overdue: boolean;
  patient_id: number | null;
  patient_name: string | null;
  mrn: string | null;
  admission_id: number | null;
  er_visit_id: number | null;
  ward_id: number | null;
  ward_name: string | null;
  bed_label: string | null;
  prescription_id: number | null;
  prescription_number: string | null;
  query_id: number | null;
  own_medicine_id: number | null;
  recall_id: number | null;
  recall_number: string | null;
  batch_id: number | null;
}

/** A verbal or telephone order and its countersignature (MSDS 55). */
export interface VerbalOrderOut {
  prescription_id: number;
  prescription_number: string;
  order_mode: "Written" | "Verbal" | "Telephone";
  source: "OPD" | "IPD" | "CodeRed" | "ER";
  status: "Active" | "PartiallyDispensed" | "FullyDispensed" | "Cancelled" | "Replaced" | "ExternalPrinted";
  patient_id: number;
  patient_name: string;
  mrn: string;
  admission_id: number | null;
  ticket_id: number | null;
  prescriber_id: number;
  prescriber_name: string;
  received_by: number;
  received_by_name: string;
  created_at: string;
  countersigned_at: string | null;
  countersigned_by_name: string | null;
  /** The order's time plus verbal_order_countersign_hours */
  countersign_due_at: string;
  /** Not countersigned and past its due time */
  is_overdue: boolean;
  /** Countersigned after its due time (null: not yet) */
  countersigned_late: boolean | null;
  /** The ordered lines as one text each: medicine, dose, route, frequency */
  lines: string[];
}

export interface PrescriptionDetailOut {
  prescription_id: number;
  prescription_number: string;
  patient_id: number;
  prescriber_id: number;
  ticket_id: number | null;
  admission_id: number | null;
  encounter_id: number | null;
  source: "OPD" | "IPD" | "CodeRed" | "ER";
  destination: "HospitalPharmacy" | "ExternalMarket";
  status: "Active" | "PartiallyDispensed" | "FullyDispensed" | "Cancelled" | "Replaced" | "ExternalPrinted";
  is_content_locked: boolean;
  replaced_by_id: number | null;
  notes: string | null;
  cancelled_at: string | null;
  cancel_reason: string | null;
  external_printed_at: string | null;
  /** Verbal / Telephone: written down by `received_by` for the prescriber, who countersigns it (MSDS 55) */
  order_mode: "Written" | "Verbal" | "Telephone";
  received_by: number | null;
  received_by_name: string | null;
  read_back: boolean;
  countersigned_by: number | null;
  countersigned_at: string | null;
  /** When the prescriber was reminded of a late countersignature */
  countersign_alerted_at: string | null;
  created_by: number | null;
  created_at: string;
  row_version: number;
  patient_name: string;
  mrn: string;
  prescriber_name: string;
  /** The prescriber when prescribing (MSDS 147; printed on the slip) */
  prescriber_stamp: AuthorStampOut;
  items: PrescriptionItemOut[];
  dispensations: PrescriptionDispensationOut[];
  /** The pharmacist's queries on the order, open ones first */
  queries: PrescriptionQueryOut[];
  /** Each time the slip was handed over (none: not yet) */
  handovers: PrescriptionHandoverOut[];
}

/** The author stamp of a clinical entry (MSDS IMS 147), as the author's staff record stood when they signed it (SQL hms_author_stamp / hms_employee_stamp, migration 0013 [STP]). Show it under the entry on screen and print `text` under it on paper. */
export interface AuthorStampOut {
  employee_id: number | null;
  user_id: number | null;
  name: string;
  /** Designation and specialty, e.g. "Medical Officer, General Medicine" */
  designation: string | null;
  /** Council registration, e.g. "PMDC 12345-P" or "PNC 67890" */
  registration: string | null;
  /** When the entry was signed, reported or verified */
  at: string;
  /** The printed line: name, designation, registration, date and time */
  text: string;
}

export interface PrescriptionItemOut {
  prescription_item_id: number;
  prescription_id: number;
  /** Null for an external (local market) drug */
  drug_id: number | null;
  is_external: boolean;
  external_drug_name: string | null;
  external_strength: string | null;
  external_form: string | null;
  qty_prescribed: number;
  qty_dispensed: number;
  dose_text: string | null;
  route: "Oral" | "IV" | "IM" | "SC" | "Topical" | "Inhaled" | "PR" | "SL" | "Ophthalmic" | "Otic" | "Nasal" | "Other" | null;
  frequency_code: "OD" | "BD" | "TDS" | "QID" | "Q4H" | "Q6H" | "Q8H" | "Q12H" | "HS" | "STAT" | "PRN" | "Other" | null;
  interval_hours: number | null;
  duration_days: number | null;
  instructions: string | null;
  start_at: string | null;
  end_at: string | null;
  is_prn: boolean;
  is_stat: boolean;
  /** The doctor allowed the patient to take it themselves (MSDS 70) */
  self_administration: boolean;
  item_status: "Active" | "Stopped" | "Cancelled" | "FullyDispensed";
  stopped_at: string | null;
  stopped_by: number | null;
  stop_reason: string | null;
  row_version: number;
  drug_name: string | null;
  strength: string | null;
  form: "Tablet" | "Capsule" | "Syrup" | "Suspension" | "Injection" | "Infusion" | "Cream" | "Ointment" | "Drops" | "Inhaler" | "Suppository" | "Powder" | "Consumable" | "Device" | "Other" | null;
  unit: string | null;
  /** Live pharmacy stock of the drug */
  qty_available: number | null;
  stock_status: string | null;
  qty_remaining: number;
  high_alert_category: "ConcentratedElectrolyte" | "Chemotherapy" | "Anticoagulant" | "Insulin" | "Opioid" | "Sedative" | "NeuromuscularBlocker" | "Inotrope" | "Thrombolytic" | "Psychotropic" | "HighCost" | "Other" | null;
  is_restricted: boolean | null;
  /** Medicines it looks or sounds like */
  lasa_with: string[];
}

export interface PrescriptionDispensationOut {
  dispensation_id: number;
  payment_mode: "Cash" | "Card" | "PanelCredit" | "IPDBill" | "StaffPayrollDeduction" | "CharityZakat" | "SocialWelfare";
  total_amount: number;
  dispensed_at: string;
  dispensed_by: number;
  /** The second person who checked a high-alert medicine */
  checked_by: number | null;
}

/** The pharmacist's query on an order (MSDS 51 iv), with the order it is about. */
export interface PrescriptionQueryOut {
  query_id: number;
  prescription_id: number;
  /** Null: about the whole prescription */
  prescription_item_id: number | null;
  reason: "Unclear" | "DoseOrFrequency" | "Allergy" | "Interaction" | "Duplicate" | "ChildDose" | "Restricted" | "WrongPatient" | "Other";
  question: string;
  status: "Open" | "Answered" | "Withdrawn";
  raised_by: number;
  raised_by_name: string;
  raised_at: string;
  outcome: "ConfirmedAsWritten" | "Changed" | null;
  answer: string | null;
  answered_by: number | null;
  answered_by_name: string | null;
  answered_at: string | null;
  /** The doctor who answered (MSDS 147) */
  answer_stamp: AuthorStampOut | null;
  withdrawn_by: number | null;
  withdrawn_at: string | null;
  withdraw_reason: string | null;
  row_version: number;
  prescription_number: string;
  patient_id: number;
  patient_name: string;
  mrn: string;
  admission_id: number | null;
  ticket_id: number | null;
  prescriber_id: number;
  prescriber_name: string;
  /** The queried line's medicine (null for the whole prescription) */
  drug_name: string | null;
  dose_text: string | null;
  route: "Oral" | "IV" | "IM" | "SC" | "Topical" | "Inhaled" | "PR" | "SL" | "Ophthalmic" | "Otic" | "Nasal" | "Other" | null;
  frequency_code: "OD" | "BD" | "TDS" | "QID" | "Q4H" | "Q6H" | "Q8H" | "Q12H" | "HS" | "STAT" | "PRN" | "Other" | null;
}

/** The slip handed over and the copy kept (the clinic manual, indicator 35). */
export interface PrescriptionHandoverOut {
  handover_id: number;
  handed_to: "Patient" | "Attendant";
  attendant_name: string | null;
  copy_kept: "Electronic" | "CarbonCopy" | "Scan";
  /** The scan of the signed copy in the patient's documents */
  document_id: number | null;
  handed_by: number;
  handed_by_name: string;
  handed_at: string;
}

export interface QueryAnswerIn {
  /** ConfirmedAsWritten; Changed: stop the line (or cancel the prescription) and write the new order first */
  outcome: "ConfirmedAsWritten" | "Changed";
  answer: string;
}

export interface PharmacyReasonIn {
  reason: string;
}

/** Medication safety work waiting — GET /api/v1/medication-safety/worklist (who may call: holders of medication.safety.view or patient.wristband.print). */
export function safetyWorklist(query?: { ward_id?: number | null; mine?: boolean }): Promise<MedicationWorklistItemOut[]> {
  return api<MedicationWorklistItemOut[]>("GET", withQuery(`/medication-safety/worklist`, query), undefined);
}

/** Verbal orders and their countersignatures — GET /api/v1/verbal-orders (who may call: holders of prescription.view or prescription.verbal.record). */
export function listVerbalOrders(query?: { mine?: boolean; pending?: boolean; admission_id?: number | null; limit?: number }): Promise<VerbalOrderOut[]> {
  return api<VerbalOrderOut[]>("GET", withQuery(`/verbal-orders`, query), undefined);
}

/** Countersign my verbal order — POST /api/v1/prescriptions/{prescription_id}/countersign (who may call: holders of prescription.create). */
export function countersign(prescription_id: number): Promise<PrescriptionDetailOut> {
  return api<PrescriptionDetailOut>("POST", `/prescriptions/${prescription_id}/countersign`, undefined);
}

/** The pharmacist's queries — GET /api/v1/prescription-queries (who may call: holders of prescription.view or prescription.query.raise). */
export function listQueries(query?: { status?: "Open" | "Answered" | "Withdrawn" | null; mine?: boolean; prescription_id?: number | null; limit?: number }): Promise<PrescriptionQueryOut[]> {
  return api<PrescriptionQueryOut[]>("GET", withQuery(`/prescription-queries`, query), undefined);
}

/** Answer the pharmacist's query — POST /api/v1/prescription-queries/{query_id}/answer (who may call: holders of prescription.create). */
export function answerQuery(query_id: number, body: QueryAnswerIn): Promise<PrescriptionQueryOut> {
  return api<PrescriptionQueryOut>("POST", `/prescription-queries/${query_id}/answer`, body, { idempotent: true });
}

/** Stop one medication line — POST /api/v1/prescriptions/{prescription_id}/items/{item_id}/stop (who may call: holders of prescription.cancel). */
export function stop(prescription_id: number, item_id: number, body: PharmacyReasonIn): Promise<PrescriptionDetailOut> {
  return api<PrescriptionDetailOut>("POST", `/prescriptions/${prescription_id}/items/${item_id}/stop`, body);
}

/** Prescription with remaining quantities and stock per line — GET /api/v1/prescriptions/{prescription_id} (who may call: holders of prescription.view). */
export function getPrescription(prescription_id: number): Promise<PrescriptionDetailOut> {
  return api<PrescriptionDetailOut>("GET", `/prescriptions/${prescription_id}`, undefined);
}
